// Normalise the form answers, check the dates and build the messages.
const cfg = $('Settings').first().json;
const f = $input.first().json;
const pick = (...keys) => { for (const k of keys) if (f[k] !== undefined && f[k] !== '') return String(f[k]).trim(); return ''; };
const name = pick('Full name'), email = pick('Email').toLowerCase(), phone = pick('Phone (with country code)');
const checkIn = pick('Check-in date'), checkOut = pick('Check-out date');
const guests = Number(pick('Guests')) || 1, room = pick('Room type') || 'Any', note = pick('Message').slice(0, 1000);
const day = 86400000, today = new Date(new Date().toISOString().slice(0, 10));
const a = new Date(checkIn), b = new Date(checkOut);
const nights = Math.round((b - a) / day);
const problems = [];
if (isNaN(a) || isNaN(b)) problems.push('dates missing');
else { if (a < today) problems.push('check-in is in the past'); if (nights < 1) problems.push('check-out is not after check-in'); if (nights > 60) problems.push('stay longer than 60 nights'); }
if (guests > Number(cfg.maxGuests)) problems.push(`more than ${cfg.maxGuests} guests`);
const ref = 'BK-' + Date.now().toString(36).slice(-5).toUpperCase();
const status = problems.length ? 'Check details' : 'New';
const summary = `${ref} · ${name} · ${checkIn} → ${checkOut} (${nights > 0 ? nights : '?'} nights) · ${guests} guest(s) · ${room}` + (problems.length ? ` · ⚠ ${problems.join(', ')}` : '');
return [{ json: {
  reference: ref, received_at: new Date().toISOString(), status, name, email, phone,
  check_in: checkIn, check_out: checkOut, nights: nights > 0 ? nights : '', guests, room_type: room, message: note,
  problems: problems.join(', '), summary,
} }];

